using UnityEngine;using UnityEngine.UI;
public class StaminaHUD:MonoBehaviour{public StaminaSystem stamina;public RectTransform container;public Image barPrefab;void Start(){Rebuild();}public void Rebuild(){if(!stamina||!container||!barPrefab)return;for(int i=container.childCount-1;i>=0;i--)if(container.GetChild(i).gameObject!=barPrefab.gameObject)Destroy(container.GetChild(i).gameObject);}void Update(){if(!stamina||!container)return;int max=stamina.settings.staminaBars;while(container.childCount<max){var b=Instantiate(barPrefab,container);b.gameObject.SetActive(true);}for(int i=0;i<container.childCount;i++){var im=container.GetChild(i).GetComponent<Image>();if(im){im.type=Image.Type.Filled;im.fillMethod=Image.FillMethod.Horizontal;im.fillAmount=Mathf.Clamp01(stamina.CurrentBars-i);}}}}
